import{_ as p,o as t,c as o,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"2018-08-01 Ceph Developer Monthly","description":"","frontmatter":{"title":"2018-08-01 Ceph Developer Monthly","date":"2018-08-01T00:00:00.000Z","updated":"2018-08-03T00:00:00.000Z","tags":["Ceph","分布式存储","权限控制","CSI","文件系统"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2018/2018-08-01_Ceph_Developer_Monthly.md","filePath":"posts/2018/2018-08-01_Ceph_Developer_Monthly.md","lastUpdated":1780460162000}'),l={name:"posts/2018/2018-08-01_Ceph_Developer_Monthly.md"};function s(n,e,_,a,h,C){return t(),o("div",null,[...e[0]||(e[0]=[r("<p>本次会议主要讨论了Ceph分布式存储系统的多个功能改进和优化方案，以下是会议的主要议题和决定事项：</p><ol><li><p><strong>Ceph存储池权限控制</strong>： 现有权限控制机制较为粗粒度，会议提出了引入更细粒度的角色和权限控制方案，包括存储管理员和普通用户角色，以及存储池命名空间支持，实现租户级别的图像隔离。会议还讨论了配置文件的创建、删除和调整图像大小等操作权限限制。</p></li><li><p><strong>Ceph容器存储接口（CSI）</strong>： 为了支持更灵活的存储管理，会议提出将Ceph CSI客户端模块迁移到Ceph Manager模块，统一存储管理，并开发新的命令行工具和REST API。</p></li><li><p><strong>Ceph文件系统</strong>： 会议讨论了Ceph文件系统的改进，包括将文件系统称为“卷”，子文件系统称为“子卷”，以及多个文件系统共享相同的数据池，以提升性能和可扩展性。</p></li><li><p><strong>Ceph MDS工作负载分析</strong>： 为了改进Ceph MDS的性能和可扩展性，会议提出了收集更多MDS性能指标，开发新的工具分析MDS工作负载，并改进Ceph MDS的缓存机制。</p></li><li><p><strong>Ceph OSD同步问题</strong>： 针对Ceph OSD在处理多个并发操作时可能出现的性能问题，会议提出了将PG锁从互斥锁改为读写锁，并实现同步读取功能的方案。</p></li></ol><p>会议明确了各个议题的解决方案和行动计划，为Ceph的进一步发展奠定了基础。</p>",3)])])}const S=p(l,[["render",s]]);export{d as __pageData,S as default};
